const PAYLOAD = [{"id":"pnj-grands-exiles-tobias-dorner-01","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Tobias DORNER","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Conseil des Anciens","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Tobias DORNER","real_name_source":"Tobias DORNER","nom_verite":"Oberon VADEL","nom_verite_source":"Oberon VADEL","race":"Elfes","age":"«51 ans » - ???? ans","origine":"britannique","statut":"grand administrateur","affiliations":"Corporatiste : omegacoustic","source_group":"Conseil des Anciens","source_groups":["Conseil des Anciens"],"source_pages":[5],"source_occurrences":1,"identity_keys":["Tobias DORNER","Oberon VADEL","Premier siège (elfique) : Oberon Vadel","elfique"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Premier siège (elfique) : Oberon Vadel Nom de la Réalité : Tobias DORNER Nom de la Vérité : Oberon VADEL Age : «51 ans » - ???? ans Affiliations : Corporatiste : omegacoustic Nationalité d’origine : britannique Ethnie réelle : Elfes Statut : grand administrateur Né sur Aèr, de l’illustre famille des Vadel, des elfes gris, il est venu assez tôt sur Terre. Militaire à l’origine, il désirait faire de la terre la nouvelle Terre des Elfes gris, où les épidémies les ayant ravagés grandement n’auraient pas lieu. Il devint un politicien extrêmement fin stratège au fil des millénaires en traitant entre les communautés elfiques et autres communautés locales comme expatriés. Les humains l’évoquèrent souvent dans le nord de l’Europe comme « roi des aulnes » ou « Roi des elfes » bien qu’il ne fût pas officiellement roi et encore moins de tous les elfes. Puissant combattant mais assez bon magicien également, il fut un des principaux acteurs de la « guerre magique » qui opposèrent les Mages aux créatures inhumaines maniant la magie de la Terre. Durant cette guerre, les Mages ayant vu le déclin magique, cherchèrent à accaparer l’absolue maniement des flux du monde. C’est cette guerre qui entraina un plus grand déclin de la magie sur Terre notamment et un grand massacre des elfes, très concernés. Oberon a une haine profonde contre les « Myrddin », c’est-à-dire les « Mages »"},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Tobias DORNER"],["Âge apparent","51 ans"],["Nationalité déclarée","britannique"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Premier siège (elfique) : Oberon Vadel"],["Nom de la Réalité","Tobias DORNER"],["Nom de la Vérité","Oberon VADEL"],["Âge source","«51 ans » - ???? ans"],["Affiliations","Corporatiste : omegacoustic"],["Nationalité d’origine","britannique"],["Nature réelle","Elfes"],["Statut","grand administrateur"]]},{"type":"p","style":"lore","text":"Né sur Aèr, de l’illustre famille des Vadel, des elfes gris, il est venu assez tôt sur Terre. Militaire à l’origine, il désirait faire de la terre la nouvelle Terre des Elfes gris, où les épidémies les ayant ravagés grandement n’auraient pas lieu. Il devint un politicien extrêmement fin stratège au fil des millénaires en traitant entre les communautés elfiques et autres communautés locales comme expatriés. Les humains l’évoquèrent souvent dans le nord de l’Europe comme « roi des aulnes » ou « Roi des elfes » bien qu’il ne fût pas officiellement roi et encore moins de tous les elfes. Puissant combattant mais assez bon magicien également, il fut un des principaux acteurs de la « guerre magique » qui opposèrent les Mages aux créatures inhumaines maniant la magie de la Terre. Durant cette guerre, les Mages ayant vu le déclin magique, cherchèrent à accaparer l’absolue maniement des flux du monde. C’est cette guerre qui entraina un plus grand déclin de la magie sur Terre notamment et un grand massacre des elfes, très concernés. Oberon a une haine profonde contre les « Myrddin », c’est-à-dire les « Mages »"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-dylania-alfanasievna-02","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Dylania Alfanasievna","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Conseil des Anciens","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Dylania Alfanasievna","real_name_source":"Dylania Alfanasievna","nom_verite":"Dylania Malrion","nom_verite_source":"Dylania Malrion","race":"Elfes","age":"«32 ans » - ???? ans","origine":"ukranienne","statut":"grand administrateur","affiliations":"Pègre : bratva","source_group":"Conseil des Anciens","source_groups":["Conseil des Anciens"],"source_pages":[5],"source_occurrences":1,"identity_keys":["Dylania Alfanasievna","Dylania Malrion","Deuxième siège (elfique) : Dylania Malrion","elfique"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Deuxième siège (elfique) : Dylania Malrion Nom de la Réalité : Dylania Alfanasievna Nom de la Vérité : Dylania Malrion Age : «32 ans » - ???? ans Affiliations : Pègre : bratva Nationalité d’origine : ukranienne Ethnie réelle : Elfes Statut : grand administrateur Parfois, à côté d’Ariel Nova, sur les barres du Dancing Rabbit, on peut y voir une brune, sculpturale, une trace de main sur sa peau laiteuse, s’agiter comme si sa vie en dépendait. C’est à peu près le cas en vérité et c’est -contrairement aux apparences – une personne haute placée dans la bratva. C’est Dynalia, un membre du groupe ukrainien de Drasko Vladic et c’est sa chargée de la prostitution et du commerce humain de la mafia russe, du moins celle qui gère pour Drasko. C’est, étrangement, également une très très haute personnalité du conseil des Anciens, puisque c’est la « princesse » Malrion, une haute noble de la communauté elfique. (D’origines elfe noire). Siégeant au conseil, elle a très à cœur de garder un contact avec les humains et de mêler les communautés. Elle déteste Alayna Daewynn et d’autres elfes assez farouches. Elle s’entends très mal avec Titania de plus."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Dylania Alfanasievna"],["Âge apparent","32 ans"],["Nationalité déclarée","ukranienne"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Deuxième siège (elfique) : Dylania Malrion"],["Nom de la Réalité","Dylania Alfanasievna"],["Nom de la Vérité","Dylania Malrion"],["Âge source","«32 ans » - ???? ans"],["Affiliations","Pègre : bratva"],["Nationalité d’origine","ukranienne"],["Nature réelle","Elfes"],["Statut","grand administrateur"]]},{"type":"p","style":"lore","text":"Parfois, à côté d’Ariel Nova, sur les barres du Dancing Rabbit, on peut y voir une brune, sculpturale, une trace de main sur sa peau laiteuse, s’agiter comme si sa vie en dépendait. C’est à peu près le cas en vérité et c’est -contrairement aux apparences – une personne haute placée dans la bratva. C’est Dynalia, un membre du groupe ukrainien de Drasko Vladic et c’est sa chargée de la prostitution et du commerce humain de la mafia russe, du moins celle qui gère pour Drasko. C’est, étrangement, également une très très haute personnalité du conseil des Anciens, puisque c’est la « princesse » Malrion, une haute noble de la communauté elfique. (D’origines elfe noire). Siégeant au conseil, elle a très à cœur de garder un contact avec les humains et de mêler les communautés. Elle déteste Alayna Daewynn et d’autres elfes assez farouches. Elle s’entends très mal avec Titania de plus."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-sahamena-lannis-03","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Sahamena Lannis","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Conseil des Anciens","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Sahamena Lannis","real_name_source":"Sahamena Lannis","nom_verite":"Sahamena Lanyth","nom_verite_source":"Sahamena Lanyth","race":"Elfes","age":"«39 ans » - ???? ans","origine":"américaine","statut":"grand administrateur","affiliations":"Crawlers : insurgés","source_group":"Conseil des Anciens","source_groups":["Conseil des Anciens"],"source_pages":[6],"source_occurrences":1,"identity_keys":["Sahamena Lannis","Sahamena Lanyth","Troisième siège (elfique) : Sahamena Lanyth","elfique"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Troisième siège (elfique) : Sahamena Lanyth Nom de la Réalité : Sahamena Lannis Nom de la Vérité : Sahamena Lanyth Age : «39 ans » - ???? ans Affiliations : Crawlers : insurgés Nationalité d’origine : américaine Ethnie réelle : Elfes Statut : grand administrateur Issue de la grande famille Lanyth (origine elfes sylvains), elle est membre du conseil des Anciens afin de garder une place importante, nombreux sont les elfes ayant jugé leur communauté suffisante pour s’en défaire et ayant été sévèrement punis. Malgré une nature assez sauvage, d’elfe forestière, elle n’a aucun souci à vivre dans les forêts urbaines. C’est la plus grande rivale d’Alayna Daewyn. En tant qu’humaine, elle est à la tête d’insurgés environnementalistes, elle lutte contre la non￾réglementation internationale sur les territoires corporatifs. Elle notamment tué plusieurs cadres de yellowfooden « vengeance » de la disparition officielle de 25 espèces sud-américaines dont le Tapir, le jaguar et l’anaconda jaune à la suite de l’implantation de megausines. Elle est aussi intransigeante en tant que crawler qu’elle est diplomate au conseil, elle place au-dessus de tout l’intérêt des elfes néanmoins, bien au-dessus de l’intérêt des autres exilés."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Sahamena Lannis"],["Âge apparent","39 ans"],["Nationalité déclarée","américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Troisième siège (elfique) : Sahamena Lanyth"],["Nom de la Réalité","Sahamena Lannis"],["Nom de la Vérité","Sahamena Lanyth"],["Âge source","«39 ans » - ???? ans"],["Affiliations","Crawlers : insurgés"],["Nationalité d’origine","américaine"],["Nature réelle","Elfes"],["Statut","grand administrateur"]]},{"type":"p","style":"lore","text":"Issue de la grande famille Lanyth (origine elfes sylvains), elle est membre du conseil des Anciens afin de garder une place importante, nombreux sont les elfes ayant jugé leur communauté suffisante pour s’en défaire et ayant été sévèrement punis. Malgré une nature assez sauvage, d’elfe forestière, elle n’a aucun souci à vivre dans les forêts urbaines. C’est la plus grande rivale d’Alayna Daewyn. En tant qu’humaine, elle est à la tête d’insurgés environnementalistes, elle lutte contre la non￾réglementation internationale sur les territoires corporatifs. Elle notamment tué plusieurs cadres de yellowfooden « vengeance » de la disparition officielle de 25 espèces sud-américaines dont le Tapir, le jaguar et l’anaconda jaune à la suite de l’implantation de megausines. Elle est aussi intransigeante en tant que crawler qu’elle est diplomate au conseil, elle place au-dessus de tout l’intérêt des elfes néanmoins, bien au-dessus de l’intérêt des autres exilés."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-samantha-maxwell-04","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Samantha MAXWELL","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Conseil des Anciens","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Samantha MAXWELL","real_name_source":"Samantha MAXWELL","nom_verite":"Samanthea MALANWE","nom_verite_source":"Samanthea MALANWE","race":"Azménorienne","age":"«35 ans » - ???? ans","origine":"américaine","statut":"grand administrateur","affiliations":"Crawlers : Fixers","source_group":"Conseil des Anciens","source_groups":["Conseil des Anciens"],"source_pages":[6],"source_occurrences":1,"identity_keys":["Samantha MAXWELL","Samanthea MALANWE","Siège (azménorien) : Samanthea Malanwe","azménorien"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Siège (azménorien) : Samanthea Malanwe Nom de la Réalité : Samantha MAXWELL Nom de la Vérité : Samanthea MALANWE Age : «35 ans » - ???? ans Affiliations : Crawlers : Fixers Nationalité d’origine : américaine Ethnie réelle : Azménorienne Statut : grand administrateur Samantha est la fixer numéro 1 de Las Vegas, au point que tout crawler qui a bossé au moins une fois à Las Vegas a forcément rencontré un de ses subordonnés. Très élégante et ultrariche, elle est en bon termes avec toutes les corporations présentes et a complétement oblitéré la branche de la Blanchisserie à las Vegas. Derrière son image de femme fatale se vautrant dans le luxe, c’est la conseillère militaire du conseil des Anciens. C’est une chasseuse « d’Aspérités », c’est-à-dire tous les cas surnaturels ou fantastiques de manifestation pouvant menacer l’harmonie de l’Hologramme. C’est une guerrière émérite et, elle a été grandement troublée que le hunt15 soit composé de gens encore au-dessus d’elle tant elle est performante. Elle a perdu un bras et pratiquement la vie face au « grand Traqueur », heureusement, elle a été régénérée par Oberon. Elle aime profondément Sil’Elaith, la guide."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Samantha MAXWELL"],["Âge apparent","35 ans"],["Nationalité déclarée","américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Siège (azménorien) : Samanthea Malanwe"],["Nom de la Réalité","Samantha MAXWELL"],["Nom de la Vérité","Samanthea MALANWE"],["Âge source","«35 ans » - ???? ans"],["Affiliations","Crawlers : Fixers"],["Nationalité d’origine","américaine"],["Nature réelle","Azménorienne"],["Statut","grand administrateur"]]},{"type":"p","style":"lore","text":"Samantha est la fixer numéro 1 de Las Vegas, au point que tout crawler qui a bossé au moins une fois à Las Vegas a forcément rencontré un de ses subordonnés. Très élégante et ultrariche, elle est en bon termes avec toutes les corporations présentes et a complétement oblitéré la branche de la Blanchisserie à las Vegas. Derrière son image de femme fatale se vautrant dans le luxe, c’est la conseillère militaire du conseil des Anciens. C’est une chasseuse « d’Aspérités », c’est-à-dire tous les cas surnaturels ou fantastiques de manifestation pouvant menacer l’harmonie de l’Hologramme. C’est une guerrière émérite et, elle a été grandement troublée que le hunt15 soit composé de gens encore au-dessus d’elle tant elle est performante. Elle a perdu un bras et pratiquement la vie face au « grand Traqueur », heureusement, elle a été régénérée par Oberon. Elle aime profondément Sil’Elaith, la guide."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-mike-kirk-05","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Mike KIRK","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Conseil des Anciens","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Mike KIRK","real_name_source":"Mike KIRK","nom_verite":"Malderic IRGARIN","nom_verite_source":"Malderic IRGARIN","race":"naine","age":"« 47 ans » - ???","origine":"Canadienne","statut":"grand administrateur","affiliations":"chasseurs fantastiques / corporatif : seawares","source_group":"Conseil des Anciens","source_groups":["Conseil des Anciens"],"source_pages":[7],"source_occurrences":1,"identity_keys":["Mike KIRK","Malderic IRGARIN","Premier siège (nain) : Mike Irgarin","nain"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Premier siège (nain) : Mike Irgarin Nom de la Réalité : Mike KIRK Nom de la Vérité : Malderic IRGARIN Age : « 47 ans » - ??? Affiliations : chasseurs fantastiques / corporatif : seawares Nationalité d’origine : Canadienne Ethnie réelle : naine Statut : grand administrateur Malderic est un des plus anciens nains sur Terre, au point qu’il est né sur Aèr. C’était un ami de Shorolth, le dragon fondateur. Il est encore ami avec lui, puisqu’ils travaillent ensemble pour Sil’Elaith. Si Maderic est le meilleur ami du dragon, il vénère la Vala’eraï lui servant de patronne comme une déesse et sa loyauté ne va qu’à elle. Il est purement immortel tant que personne n’envoie au Néant Telepinu, en effet, « l’anneau visqueux » qu’il se forgea après avoir vaincu la créature rattacha son âme aux pouvoirs du fléau mineur, non pas en étant corrompu mais par un lien de balance. Rendu mortel depuis que Veronica silver Divisa Telepinu en deux : un esprit et ses pouvoirs séparément, il ne cherche pas à protéger son immortalité, il continue de se battre contre les créatures des abysses et les nains renégats. C’est un des premiers membres du conseil des Anciens, un de ses fondateurs même si certains le voient comme un archaïque conseiller loin des enjeux actuels, il reste respecté."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Mike KIRK"],["Âge apparent","47 ans"],["Nationalité déclarée","Canadienne"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Premier siège (nain) : Mike Irgarin"],["Nom de la Réalité","Mike KIRK"],["Nom de la Vérité","Malderic IRGARIN"],["Âge source","« 47 ans » - ???"],["Affiliations","chasseurs fantastiques / corporatif : seawares"],["Nationalité d’origine","Canadienne"],["Nature réelle","naine"],["Statut","grand administrateur"]]},{"type":"p","style":"lore","text":"Malderic est un des plus anciens nains sur Terre, au point qu’il est né sur Aèr. C’était un ami de Shorolth, le dragon fondateur. Il est encore ami avec lui, puisqu’ils travaillent ensemble pour Sil’Elaith. Si Maderic est le meilleur ami du dragon, il vénère la Vala’eraï lui servant de patronne comme une déesse et sa loyauté ne va qu’à elle. Il est purement immortel tant que personne n’envoie au Néant Telepinu, en effet, « l’anneau visqueux » qu’il se forgea après avoir vaincu la créature rattacha son âme aux pouvoirs du fléau mineur, non pas en étant corrompu mais par un lien de balance. Rendu mortel depuis que Veronica silver Divisa Telepinu en deux : un esprit et ses pouvoirs séparément, il ne cherche pas à protéger son immortalité, il continue de se battre contre les créatures des abysses et les nains renégats. C’est un des premiers membres du conseil des Anciens, un de ses fondateurs même si certains le voient comme un archaïque conseiller loin des enjeux actuels, il reste respecté."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-roberrick-reimer-06","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Roberrick Reimer","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Conseil des Anciens","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Roberrick Reimer","real_name_source":"Roberrick Reimer","nom_verite":"","nom_verite_source":"","race":"naine","age":"43 ans","origine":"néerlandaise","statut":"grand administrateur","affiliations":"corporations : Dwarfood","source_group":"Conseil des Anciens","source_groups":["Conseil des Anciens"],"source_pages":[7],"source_occurrences":1,"identity_keys":["Roberrick Reimer","Deuxième siège (nain) : Roberrick Reimer","nain"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Deuxième siège (nain) : Roberrick Reimer Nom de la Réalité : Roberrick Reimer Age : 43 ans Affiliations : corporations : Dwarfood Nationalité d’origine : néerlandaise Ethnie réelle : naine Statut : grand administrateur Lointain descendant d’une branche poussive des Bellentrin, Roberrick est né sur Terre, d’une longue lignée de Whurtens Terriens. C’est un des membres du conseil les plus jeunes mais aussi un des plus conscients des enjeux de la Réalité, élections, religions, évènements sportifs et guerre évidemment, pour lui ces événements sont plus importants que les petits conflits éternels de la Vérité. Il s’entends bien avec Sil’elaith, en tant que président corporatif, moins avec les plus « crawlers » du conseil. Il doit souvent gérer des conflits internes dans les familles de nains, Son cousin, Russell Vinderbeck, était membre du conseil avant lui, quelques années auparavant, tant dans la Vérité que la Réalité, leur rivalité est souvent source de problèmes. Malgré ses airs de patibulaire président corporatif, Roberrick entretient un corps de combattant, ancien mercenaire, la moindre occasion de passer à l’action est bonne, bien que trop rare."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Roberrick Reimer"],["Âge déclaré","43 ans"],["Nationalité déclarée","néerlandaise"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Deuxième siège (nain) : Roberrick Reimer"],["Nom de la Réalité","Roberrick Reimer"],["Âge source","43 ans"],["Affiliations","corporations : Dwarfood"],["Nationalité d’origine","néerlandaise"],["Nature réelle","naine"],["Statut","grand administrateur"]]},{"type":"p","style":"lore","text":"Lointain descendant d’une branche poussive des Bellentrin, Roberrick est né sur Terre, d’une longue lignée de Whurtens Terriens. C’est un des membres du conseil les plus jeunes mais aussi un des plus conscients des enjeux de la Réalité, élections, religions, évènements sportifs et guerre évidemment, pour lui ces événements sont plus importants que les petits conflits éternels de la Vérité. Il s’entends bien avec Sil’elaith, en tant que président corporatif, moins avec les plus « crawlers » du conseil. Il doit souvent gérer des conflits internes dans les familles de nains, Son cousin, Russell Vinderbeck, était membre du conseil avant lui, quelques années auparavant, tant dans la Vérité que la Réalité, leur rivalité est souvent source de problèmes. Malgré ses airs de patibulaire président corporatif, Roberrick entretient un corps de combattant, ancien mercenaire, la moindre occasion de passer à l’action est bonne, bien que trop rare."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-cassandra-traxmann-07","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Cassandra Traxmann","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Conseil des Anciens","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Cassandra Traxmann","real_name_source":"Cassandra Traxmann – « Cass Trash On »","nom_verite":"","nom_verite_source":"","race":"Nains","age":"«30 ans », ????","origine":"Américaine","statut":"grand administrateur","affiliations":"crawlers : cyppers","source_group":"Conseil des Anciens","source_groups":["Conseil des Anciens"],"source_pages":[8],"source_occurrences":1,"identity_keys":["Cassandra Traxmann – « Cass Trash On »","Cassandra Traxmann","Cass Trash On","Troisième siège (nain) : « Cass Trash »","Cass Trash","nain"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Troisième siège (nain) : « Cass Trash » Nom de la Réalité : Cassandra Traxmann – « Cass Trash On » Age : «30 ans », ???? Affiliations : crawlers : cyppers Nationalité d’origine : Américaine Ethnie réelle : Nains Statut : grand administrateur Dans la réalité, Cassandra Traxmann est une crawler, une meditech spécialisée « cypper », elle sait à peu près tout réparer et a tout appris à une certaine Phoebe d’ailleurs. C’est un génie de la mécanique qui bosse très souvent avec les insurgés ou bien les chasseurs de prime, ; sans distinction, elle se fiche bien de comment on utilise ce qu’elle fabrique. Dans la Vérité, c’est une grande administratrice du conseil des anciens et une très ancienne naine. Ironiquement, elle n’a jamais été ingénieur, cette descendante royale a toujours été dans la diplomatie et l’administratif, ce n’est que très récemment qu’elle s’est mise à la technologie, comme passe-temps. « Cass trash on » est un surnom voulant évoquer « Castration », en effet, elle a souvent une clé à molette ou un marteau en main et frappe l’entre-cuisse de ses interlocuteurs, souvent plus grands qu’elle, homme ou femme, ça ne fait jamais du bien. Son gantelet gauche rivalise avec les meilleures augmentations, et broie l’acier le plus résistant, mieux vaut éviter les duels de force avec elle."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Cassandra Traxmann"],["Âge apparent","30 ans"],["Nationalité déclarée","Américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Troisième siège (nain) : « Cass Trash »"],["Nom de la Réalité","Cassandra Traxmann – « Cass Trash On »"],["Âge source","«30 ans », ????"],["Affiliations","crawlers : cyppers"],["Nationalité d’origine","Américaine"],["Nature réelle","Nains"],["Statut","grand administrateur"]]},{"type":"p","style":"lore","text":"Dans la réalité, Cassandra Traxmann est une crawler, une meditech spécialisée « cypper », elle sait à peu près tout réparer et a tout appris à une certaine Phoebe d’ailleurs. C’est un génie de la mécanique qui bosse très souvent avec les insurgés ou bien les chasseurs de prime, ; sans distinction, elle se fiche bien de comment on utilise ce qu’elle fabrique. Dans la Vérité, c’est une grande administratrice du conseil des anciens et une très ancienne naine. Ironiquement, elle n’a jamais été ingénieur, cette descendante royale a toujours été dans la diplomatie et l’administratif, ce n’est que très récemment qu’elle s’est mise à la technologie, comme passe-temps. « Cass trash on » est un surnom voulant évoquer « Castration », en effet, elle a souvent une clé à molette ou un marteau en main et frappe l’entre-cuisse de ses interlocuteurs, souvent plus grands qu’elle, homme ou femme, ça ne fait jamais du bien. Son gantelet gauche rivalise avec les meilleures augmentations, et broie l’acier le plus résistant, mieux vaut éviter les duels de force avec elle."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-alexander-shorolth-08","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Alexander SHOROLTH","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Conseil des Anciens","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Alexander SHOROLTH","real_name_source":"Alexander SHOROLTH","nom_verite":"Shorolth","nom_verite_source":"Shorolth","race":"Dragons","age":"« 47 ans » - ???? ans","origine":"britannique","statut":"grand administrateur","affiliations":"corporations : Seawarres","source_group":"Conseil des Anciens","source_groups":["Conseil des Anciens"],"source_pages":[8],"source_occurrences":1,"identity_keys":["Alexander SHOROLTH","Shorolth","Siège (dragon) : Shorolth","dragon"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Siège (dragon) : Shorolth Nom de la Réalité : Alexander SHOROLTH Nom de la Vérité : Shorolth Age : « 47 ans » - ???? ans Affiliations : corporations : Seawarres Nationalité d’origine : britannique Ethnie réelle : Dragons Statut : grand administrateur Shorolth est le fondateur dragon, il a une couleur blanche éclatante et immaculée. Gravement blessé autrefois, ce furent les archanges qui le trouvèrent endormi pendant leur guerre. Afin de ne pas le voir prendre le parti des démons et des dragons, Sil’Elaith l’amena sur Terre pour l’éloigner avant son éveil, elle le déposa sur le continent d’Hyperborée où il continua de dormir longtemps jusqu’à la chute de l’Atlantide, réveillé par l’afflux d’Aseryn s’exilant sur le continent nordique. Il n’a jamais tenu rigueur à celle qui devint son amie, quant au fait d’avoir été amené sur Terre. Indépendant, il n’a jamais obéi à personne et s’isola pour dormir après avoir profité d’une déesse d’Aèr venue voir sa fille. Sil le retrouva par hasard, sur l’archipel Britannique, et le garda avec elle à Seawares. Shorolth a causé quelques graves soucis, il a copulé avec un fléau majeur (Shaoggith) et engendré des myriades de fléaux mineurs draconiques, il a engendré Zadraphon avec la déesse de la lumière sur Aèr, un terrible mais innocent dragon céleste, il a aussi créé son ordre de chevaliers dragons sur Terre, avec Siegfried, Beowulf et George. Il n’écoute quasiment rien au conseil. Hormis l’avis de Sil, la suivant presque toujours, ce qui cause des soucis étiques, avec trois sièges liés à Seawares, le conseil est assez déséquilibré."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Alexander SHOROLTH"],["Âge apparent","47 ans"],["Nationalité déclarée","britannique"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Siège (dragon) : Shorolth"],["Nom de la Réalité","Alexander SHOROLTH"],["Nom de la Vérité","Shorolth"],["Âge source","« 47 ans » - ???? ans"],["Affiliations","corporations : Seawarres"],["Nationalité d’origine","britannique"],["Nature réelle","Dragons"],["Statut","grand administrateur"]]},{"type":"p","style":"lore","text":"Shorolth est le fondateur dragon, il a une couleur blanche éclatante et immaculée. Gravement blessé autrefois, ce furent les archanges qui le trouvèrent endormi pendant leur guerre. Afin de ne pas le voir prendre le parti des démons et des dragons, Sil’Elaith l’amena sur Terre pour l’éloigner avant son éveil, elle le déposa sur le continent d’Hyperborée où il continua de dormir longtemps jusqu’à la chute de l’Atlantide, réveillé par l’afflux d’Aseryn s’exilant sur le continent nordique. Il n’a jamais tenu rigueur à celle qui devint son amie, quant au fait d’avoir été amené sur Terre. Indépendant, il n’a jamais obéi à personne et s’isola pour dormir après avoir profité d’une déesse d’Aèr venue voir sa fille. Sil le retrouva par hasard, sur l’archipel Britannique, et le garda avec elle à Seawares. Shorolth a causé quelques graves soucis, il a copulé avec un fléau majeur (Shaoggith) et engendré des myriades de fléaux mineurs draconiques, il a engendré Zadraphon avec la déesse de la lumière sur Aèr, un terrible mais innocent dragon céleste, il a aussi créé son ordre de chevaliers dragons sur Terre, avec Siegfried, Beowulf et George. Il n’écoute quasiment rien au conseil. Hormis l’avis de Sil, la suivant presque toujours, ce qui cause des soucis étiques, avec trois sièges liés à Seawares, le conseil est assez déséquilibré."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-karl-bartram-09","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Karl Bartram","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Conseil des Anciens","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Karl Bartram","real_name_source":"Karl Bartram","nom_verite":"","nom_verite_source":"_","race":"Berserk","age":"«52 ans » - ???? ans","origine":"Américaine","statut":"grand administrateur","affiliations":"Crawlers : Cyppers","source_group":"Conseil des Anciens","source_groups":["Conseil des Anciens"],"source_pages":[9],"source_occurrences":1,"identity_keys":["Karl Bartram","Siège (minorités) : Karl Bartram","minorités"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Siège (minorités) : Karl Bartram Nom de la Réalité : Karl Bartram Nom de la Vérité : _ Age : «52 ans » - ???? ans Affiliations : Crawlers : Cyppers Nationalité d’origine : Américaine Ethnie réelle : Berserk Statut : grand administrateur Karl est le jeune frère d’Arthur Bartram. C’est un cypper, un crawler qui est versé dans la mécanique, les pièges, la construction, les explosifs. Il était un ancien démineur du LAPD avant la guerre et pendant la guerre il a fait partie d’équipe du terrain du PCRC. En 2032, on lui doit la fin de la mafia moldave. Les parrains de cette mafia en Californie avaient une tour, la « Moletower » et détenait une grande part des entreprises indépendantes de forage. Payé par seawares pour calmer ces concurrents agressifs, il entra, seul, et sabota toute la tour, tuant les parrains et enterrant vivant leurs sbires. C’est un ami de Raiser bien qu’il n’aide qu’occasionnellement l’insurrection. C’était un ami de John Silver même si plus lointain qu’Henry Edwards ou Franklin Bentley ne l’étaient. Les Berserks sont très rares sur Terre, Bartram a rassemblé la majorité de ceux qu’il connaissait chez les Hell Angels, mais étant incontrôlable c’est son frère, Karl qui a obtenu le siège au conseil, même si peu de réunion se font avec lui, le conseil ne le contactant pas souvent puisqu’Oberon ne le supporte pas. Il était très ami avec Mirrissi, l’ancienne maitresse de la Chasse Fantastique, c’est l’autre raison de son écartement. Comme son frère, il est immortel, étant un héros de la guerre magique. Il est détesté par les Mages, puisque les archives le surnomment « L’embrocheur des Loges »"},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Karl Bartram"],["Âge apparent","52 ans"],["Nationalité déclarée","Américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Siège (minorités) : Karl Bartram"],["Nom de la Réalité","Karl Bartram"],["Nom de la Vérité","_"],["Âge source","«52 ans » - ???? ans"],["Affiliations","Crawlers : Cyppers"],["Nationalité d’origine","Américaine"],["Nature réelle","Berserk"],["Statut","grand administrateur"]]},{"type":"p","style":"lore","text":"Karl est le jeune frère d’Arthur Bartram. C’est un cypper, un crawler qui est versé dans la mécanique, les pièges, la construction, les explosifs. Il était un ancien démineur du LAPD avant la guerre et pendant la guerre il a fait partie d’équipe du terrain du PCRC. En 2032, on lui doit la fin de la mafia moldave. Les parrains de cette mafia en Californie avaient une tour, la « Moletower » et détenait une grande part des entreprises indépendantes de forage. Payé par seawares pour calmer ces concurrents agressifs, il entra, seul, et sabota toute la tour, tuant les parrains et enterrant vivant leurs sbires. C’est un ami de Raiser bien qu’il n’aide qu’occasionnellement l’insurrection. C’était un ami de John Silver même si plus lointain qu’Henry Edwards ou Franklin Bentley ne l’étaient. Les Berserks sont très rares sur Terre, Bartram a rassemblé la majorité de ceux qu’il connaissait chez les Hell Angels, mais étant incontrôlable c’est son frère, Karl qui a obtenu le siège au conseil, même si peu de réunion se font avec lui, le conseil ne le contactant pas souvent puisqu’Oberon ne le supporte pas. Il était très ami avec Mirrissi, l’ancienne maitresse de la Chasse Fantastique, c’est l’autre raison de son écartement. Comme son frère, il est immortel, étant un héros de la guerre magique. Il est détesté par les Mages, puisque les archives le surnomment « L’embrocheur des Loges »"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-silia-ellen-sky-10","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Silia-Ellen SKY","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Conseil des Anciens","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Silia-Ellen SKY","real_name_source":"Silia-Ellen SKY","nom_verite":"Sil’Elaith","nom_verite_source":"Sil’Elaith","race":"vala’Eraï","age":"34 ans","origine":"Galloise","statut":"grand administrateur- Guide","affiliations":"Corporations : seawares","source_group":"Conseil des Anciens","source_groups":["Conseil des Anciens"],"source_pages":[9],"source_occurrences":1,"identity_keys":["Silia-Ellen SKY","Sil’Elaith","présidence : Sil’Elaith"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"présidence : Sil’Elaith Nom de la Réalité : Silia-Ellen SKY Nom de la Vérité : Sil’Elaith Age : 34 ans Affiliations : Corporations : seawares Nationalité d’origine : Galloise Ethnie réelle : vala’Eraï Statut : grand administrateur- Guide Sur la scène internationale, Silia est une présidente corporative assez discrète, elle s’implique peu politiquement, elle provoque peu de conflits, elle n’a besoin de personne, traite avec Ocean Master, et Wellespring, ses principaux interlocuteurs, parfois Byron industrie et elle progresse sans aucune limite dans le développement de la vie sur les fonds marins. C’était la Guide des Archanges, mais elle n’a pu les empêcher de mener de graves guerres sur Aèr, mais aussi sur Terre avec Elynea à leur tête. Elle est assez peu aimée de Belial et des dieux, car elle devait instruire Elynea, ils craignaient qu’elle n’en fasse une puissante rivale et l’ont empêché de jouer ce rôle, ce qui a rendu Elynea possiblement pire encore que ses ancêtres sur Aèr vu ce qu’ils lui firent vivre. Sil est incroyablement ancienne et d’une grande sagesse, elle a vécu, fait de nombreuses erreurs, parfois tragiques et désormais, elle est la Guide non plus des archanges mais de tous les exilés. Son rôle n’est pas de décider mais proposer les bons choix au conseil. Autrefois, elle essaya d’intégrer les exilés de Gaerras à ce conseil, ainsi que les nuisibles d’Aèr, mais ce fut un échec, Mirrissi, la reine de la chasse fantastique les attaqua et brisa la diplomatie."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Silia-Ellen SKY"],["Âge déclaré","34 ans"],["Nationalité déclarée","Galloise"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","présidence : Sil’Elaith"],["Nom de la Réalité","Silia-Ellen SKY"],["Nom de la Vérité","Sil’Elaith"],["Âge source","34 ans"],["Affiliations","Corporations : seawares"],["Nationalité d’origine","Galloise"],["Nature réelle","vala’Eraï"],["Statut","grand administrateur- Guide"]]},{"type":"p","style":"lore","text":"Sur la scène internationale, Silia est une présidente corporative assez discrète, elle s’implique peu politiquement, elle provoque peu de conflits, elle n’a besoin de personne, traite avec Ocean Master, et Wellespring, ses principaux interlocuteurs, parfois Byron industrie et elle progresse sans aucune limite dans le développement de la vie sur les fonds marins. C’était la Guide des Archanges, mais elle n’a pu les empêcher de mener de graves guerres sur Aèr, mais aussi sur Terre avec Elynea à leur tête. Elle est assez peu aimée de Belial et des dieux, car elle devait instruire Elynea, ils craignaient qu’elle n’en fasse une puissante rivale et l’ont empêché de jouer ce rôle, ce qui a rendu Elynea possiblement pire encore que ses ancêtres sur Aèr vu ce qu’ils lui firent vivre. Sil est incroyablement ancienne et d’une grande sagesse, elle a vécu, fait de nombreuses erreurs, parfois tragiques et désormais, elle est la Guide non plus des archanges mais de tous les exilés. Son rôle n’est pas de décider mais proposer les bons choix au conseil. Autrefois, elle essaya d’intégrer les exilés de Gaerras à ce conseil, ainsi que les nuisibles d’Aèr, mais ce fut un échec, Mirrissi, la reine de la chasse fantastique les attaqua et brisa la diplomatie."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-gawel-prowacjesky-11","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Gawel PROWACJESKY","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Syndicat de Jade","Hordes orques","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Gawel PROWACJESKY","real_name_source":"Gawel PROWACJESKY","nom_verite":"Gaar’Kha","nom_verite_source":"Gaar’Kha","race":"Thukars (orcs)","age":"« 38 ans » - 38 ans","origine":"polonaise","statut":"","affiliations":"gouvernement – pègre : syndicat de jade","source_group":"Syndicat de Jade","source_groups":["Syndicat de Jade","Hordes orques"],"source_pages":[11,28],"source_occurrences":2,"identity_keys":["Gawel PROWACJESKY","Gaar’Kha","Chef (orc) : Gaar’Kha","orc","Horde des marais : Gaar’Kha"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Chef (orc) : Gaar’Kha Nom de la Réalité : Gawel PROWACJESKY Nom de la Vérité : Gaar’Kha Age : « 38 ans » - 38 ans Affiliations : gouvernement – pègre : syndicat de jade Nationalité d’origine : polonaise Ethnie réelle : Thukars (orcs) Clan : Horde des marais Rang dans le syndicat : Maitre Né sur Terre, Gaar’Kha est un chef d’une petite horde qui a très longtemps vivoté pacifiquement en Pologne, souvent mobilisée comme des guerriers exceptionnels, le temps de conflits, personne ne connait cette horde ni de nom de héros en faisant partie. Quand, pendant la guerre de 22-28, Gaar décida de partir pour les Etats-Unis, avec sa horde, le mouvement changea la destinée des siens. Ambitieux et sanguinaire, il tua et intrigua pour se frayer un chemin dans le syndicat de jade. Il s’imposa sur des grands noms par une intelligence rare. Profitant que Ni Ashorn ni Atreesha ne soient du Syndicat, il façonna ce dernier à son image, plus violent, plus cruel, plus moderne. S’il passe pour un bouffon européen parlant à peine anglais et représentant le gouvernement de Dina Page parfois, dans la vérité, c’est loin d’être le même homme, quand il passe son costume de luxe il impose autant que n’importe quel mieux du Comité de Svetlana et quand il enfile son armure assistée on le craint autant qu’A-man. Il veut que les autres orcs et gobelins soient soumis à lui, moins ils ont d’honneur, plus il apprécie cela. --- AUTRE OCCURRENCE DU MÊME PERSONNAGE --- Horde des marais : Gaar’Kha Nom de la Réalité : Gawel PROWACJESKY Nom de la Vérité : Gaar’Kha Age : « 38 ans » - 38 ans Affiliations : gouvernement – pègre : syndicat de jade Nationalité d’origine : polonaise Ethnie réelle : Orques (thulkar) Titre de la horde : Maitre de horde Né sur Terre, Gaar’Kha est un chef d’une petite horde qui a très longtemps vivoté pacifiquement en Pologne, souvent mobilisée comme des guerriers exceptionnels, le temps de conflits, personne ne connait cette horde ni de nom de héros en faisant partie. Quand, pendant la guerre de 22-28, Gaar décida de partir pour les Etats-Unis, avec sa horde, le mouvement changea la destinée des siens. Ambitieux et sanguinaire, il tua et intrigua pour se frayer un chemin dans le syndicat de jade. Il s’imposa sur des grands noms par une intelligence rare. Profitant que Ni Ashorn ni Atreesha ne soient du Syndicat, il façonna ce dernier à son image, plus violent, plus cruel, plus moderne. S’il passe pour un bouffon européen parlant à peine anglais et représentant le gouvernement de Dina Page parfois, dans la vérité, c’est loin d’être le même homme, quand il passe son costume de luxe il impose autant que n’importe quel mieux du Comité de Svetlana et quand il enfile son armure assistée on le craint autant qu’A-man. Il veut que les autres orcs et gobelins soient soumis à lui, moins ils ont d’honneur, plus il apprécie cela."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Gawel PROWACJESKY"],["Âge apparent","38 ans"],["Nationalité déclarée","polonaise"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Chef (orc) : Gaar’Kha / Horde des marais : Gaar’Kha"],["Nom de la Réalité","Gawel PROWACJESKY"],["Nom de la Vérité","Gaar’Kha"],["Âge source","« 38 ans » - 38 ans"],["Affiliations","gouvernement – pègre : syndicat de jade"],["Nationalité d’origine","polonaise"],["Nature réelle","Thukars (orcs)"],["Clan","Horde des marais"],["Rang dans le Syndicat","Maitre"],["Occurrences dans le document","2 (Syndicat de Jade ; Hordes orques)"]]},{"type":"p","style":"lore","text":"Né sur Terre, Gaar’Kha est un chef d’une petite horde qui a très longtemps vivoté pacifiquement en Pologne, souvent mobilisée comme des guerriers exceptionnels, le temps de conflits, personne ne connait cette horde ni de nom de héros en faisant partie. Quand, pendant la guerre de 22-28, Gaar décida de partir pour les Etats-Unis, avec sa horde, le mouvement changea la destinée des siens. Ambitieux et sanguinaire, il tua et intrigua pour se frayer un chemin dans le syndicat de jade. Il s’imposa sur des grands noms par une intelligence rare. Profitant que Ni Ashorn ni Atreesha ne soient du Syndicat, il façonna ce dernier à son image, plus violent, plus cruel, plus moderne. S’il passe pour un bouffon européen parlant à peine anglais et représentant le gouvernement de Dina Page parfois, dans la vérité, c’est loin d’être le même homme, quand il passe son costume de luxe il impose autant que n’importe quel mieux du Comité de Svetlana et quand il enfile son armure assistée on le craint autant qu’A-man. Il veut que les autres orcs et gobelins soient soumis à lui, moins ils ont d’honneur, plus il apprécie cela. Titre de la horde : Maitre de horde Né sur Terre, Gaar’Kha est un chef d’une petite horde qui a très longtemps vivoté pacifiquement en Pologne, souvent mobilisée comme des guerriers exceptionnels, le temps de conflits, personne ne connait cette horde ni de nom de héros en faisant partie. Quand, pendant la guerre de 22-28, Gaar décida de partir pour les Etats-Unis, avec sa horde, le mouvement changea la destinée des siens. Ambitieux et sanguinaire, il tua et intrigua pour se frayer un chemin dans le syndicat de jade. Il s’imposa sur des grands noms par une intelligence rare. Profitant que Ni Ashorn ni Atreesha ne soient du Syndicat, il façonna ce dernier à son image, plus violent, plus cruel, plus moderne. S’il passe pour un bouffon européen parlant à peine anglais et représentant le gouvernement de Dina Page parfois, dans la vérité, c’est loin d’être le même homme, quand il passe son costume de luxe il impose autant que n’importe quel mieux du Comité de Svetlana et quand il enfile son armure assistée on le craint autant qu’A-man. Il veut que les autres orcs et gobelins soient soumis à lui, moins ils ont d’honneur, plus il apprécie cela."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-rydia-scaramucci-12","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Rydia Scaramucci","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Syndicat de Jade","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Rydia Scaramucci","real_name_source":"Rydia Scaramucci","nom_verite":"Ryyd’sha","nom_verite_source":"Ryyd’sha","race":"Gobelins (ashylls)","age":"«30 ans » - ???? ans","origine":"américaine","statut":"","affiliations":"Pègre : mafia italienne","source_group":"Syndicat de Jade","source_groups":["Syndicat de Jade"],"source_pages":[11],"source_occurrences":1,"identity_keys":["Rydia Scaramucci","Ryyd’sha","Premier siège (Gobelin) : Rydia Scaramucci","Gobelin"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Premier siège (Gobelin) : Rydia Scaramucci Nom de la Réalité : Rydia Scaramucci Nom de la Vérité : Ryyd’sha Age : «30 ans » - ???? ans Affiliations : Pègre : mafia italienne Nationalité d’origine : américaine Ethnie réelle : Gobelins (ashylls) Rang dans le syndicat : « Seigneur » La famille Scaramucci est assez influente à Las Vegas, et ce n’est pas pour rien que Rydia est une très proche amie d’Alessandra Luciano. C’est aussi la meilleure façon de lier pègre de la Vérité à la pègre de la réalité le plus souvent, d’avoir des agents doubles, ce qui donne de cocasses situations quand Rydia était en couple avec Renaldi Rezzini , un parrain de la famille Rezzini qui se trouvait être le parrain du clan Shaediri des rocréens, grand patron de la mafia rocréenne, sortant avec le siège numéro 2 du syndicat des jade, san avoir la moindre idée de ce qu’est un ahylll.. Lointaine descendante d’Atreesha, cette gobeline est d’une terrifiante cruauté. Elle ne prend pas vraiment de temps pour s’amuser, elle dédie tout son temps à ses affaires mafieuses, ce qui la rend impitoyable et glaciale. Elle serait probablement à la tête du syndicat de jade si Gaar ne la terrifiait pas autant, elle a si peur de lui qu’elle n’a jamais rien osé contre ce dernier. Pourtant, elle a plus de poids que l’orc dans le syndicat. Cette peur la rend loyale et assure à Gaar une certaine immunité qu’il mesure pleinement."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Rydia Scaramucci"],["Âge apparent","30 ans"],["Nationalité déclarée","américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Premier siège (Gobelin) : Rydia Scaramucci"],["Nom de la Réalité","Rydia Scaramucci"],["Nom de la Vérité","Ryyd’sha"],["Âge source","«30 ans » - ???? ans"],["Affiliations","Pègre : mafia italienne"],["Nationalité d’origine","américaine"],["Nature réelle","Gobelins (ashylls)"],["Rang dans le Syndicat","« Seigneur »"]]},{"type":"p","style":"lore","text":"La famille Scaramucci est assez influente à Las Vegas, et ce n’est pas pour rien que Rydia est une très proche amie d’Alessandra Luciano. C’est aussi la meilleure façon de lier pègre de la Vérité à la pègre de la réalité le plus souvent, d’avoir des agents doubles, ce qui donne de cocasses situations quand Rydia était en couple avec Renaldi Rezzini , un parrain de la famille Rezzini qui se trouvait être le parrain du clan Shaediri des rocréens, grand patron de la mafia rocréenne, sortant avec le siège numéro 2 du syndicat des jade, san avoir la moindre idée de ce qu’est un ahylll.. Lointaine descendante d’Atreesha, cette gobeline est d’une terrifiante cruauté. Elle ne prend pas vraiment de temps pour s’amuser, elle dédie tout son temps à ses affaires mafieuses, ce qui la rend impitoyable et glaciale. Elle serait probablement à la tête du syndicat de jade si Gaar ne la terrifiait pas autant, elle a si peur de lui qu’elle n’a jamais rien osé contre ce dernier. Pourtant, elle a plus de poids que l’orc dans le syndicat. Cette peur la rend loyale et assure à Gaar une certaine immunité qu’il mesure pleinement."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-alsha-ashorn-13","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Alsha Ashorn","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Syndicat de Jade","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Alsha Ashorn","real_name_source":"Alsha Ashorn","nom_verite":"","nom_verite_source":"","race":"Thukars (orcs)","age":"«27 ans », ????","origine":"Américaine","statut":"","affiliations":"Pègre : Syndicat de Jade","source_group":"Syndicat de Jade","source_groups":["Syndicat de Jade"],"source_pages":[12],"source_occurrences":1,"identity_keys":["Alsha Ashorn","Deuxième siège (orc) : Alsha Ashorn","orc"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Deuxième siège (orc) : Alsha Ashorn Nom de la Réalité : Alsha Ashorn Age : «27 ans », ???? Affiliations : Pègre : Syndicat de Jade Nationalité d’origine : Américaine Ethnie réelle : Thukars (orcs) Clan : Horde Divine Rang dans le syndicat : « Seigneur » Une des nombreuses filles et nièces du général Ashorn est Alsha. Ratée de la famille, elle n’a pas réussi ses grandes études et a fini par tenir un pitoyable petit bar dans un quartier abandonné. En vérité, Alsha n’a rien raté, elle a juste délaissé l’héritage militaire pour valoriser sa capacité stratégique sur ses compétences purement athlétiques. Elle est une des plus influentes personnalités du syndicat de jade. Elle peut fournir n’importe quel matériaux d’Aèr comme des métaux magiques ou bien des enchantements. Outre de l’équipement elle a toute mes informations que les gobelins récoltent, dans la Vérité comme dans la réalité. Elle n’est pas avare en information tant qu’on accepte de la considérer comme une matriarche, une « mère » et qu’on obéit les rares fois où elle donne des ordres. Elle n’obéit qu’à Atreesha en personne et parfois à son père s’il s’aventure à lui donner de la considération, plus obsédé par Siobhain ou Morrighan."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Alsha Ashorn"],["Âge apparent","27 ans"],["Nationalité déclarée","Américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Deuxième siège (orc) : Alsha Ashorn"],["Nom de la Réalité","Alsha Ashorn"],["Âge source","«27 ans », ????"],["Affiliations","Pègre : Syndicat de Jade"],["Nationalité d’origine","Américaine"],["Nature réelle","Thukars (orcs)"],["Clan","Horde Divine"],["Rang dans le Syndicat","« Seigneur »"]]},{"type":"p","style":"lore","text":"Une des nombreuses filles et nièces du général Ashorn est Alsha. Ratée de la famille, elle n’a pas réussi ses grandes études et a fini par tenir un pitoyable petit bar dans un quartier abandonné. En vérité, Alsha n’a rien raté, elle a juste délaissé l’héritage militaire pour valoriser sa capacité stratégique sur ses compétences purement athlétiques. Elle est une des plus influentes personnalités du syndicat de jade. Elle peut fournir n’importe quel matériaux d’Aèr comme des métaux magiques ou bien des enchantements. Outre de l’équipement elle a toute mes informations que les gobelins récoltent, dans la Vérité comme dans la réalité. Elle n’est pas avare en information tant qu’on accepte de la considérer comme une matriarche, une « mère » et qu’on obéit les rares fois où elle donne des ordres. Elle n’obéit qu’à Atreesha en personne et parfois à son père s’il s’aventure à lui donner de la considération, plus obsédé par Siobhain ou Morrighan."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-grands-exiles-kevin-laird-14","dataset":"verite-grands-exiles-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Kevin Laird","source":"factions_les grands exilés(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Exilés","Syndicat de Jade","Grands Exilés 2026-09"],"pnj":{"completeness":"detailed","real_name":"Kevin Laird","real_name_source":"Kevin Laird","nom_verite":"Kriilf Dirtylairs","nom_verite_source":"Kriilf Dirtylairs","race":"Kweet","age":"«65 ans » - ???? ans","origine":"américaine","statut":"","affiliations":"Crawlers : venomers","source_group":"Syndicat de Jade","source_groups":["Syndicat de Jade"],"source_pages":[12],"source_occurrences":1,"identity_keys":["Kevin Laird","Kriilf Dirtylairs","Troisième siège (Kweet) : Kevin Laird","Kweet"],"source_documents":["factions_les grands exilés(1)(1).pdf"],"source_extract":"Troisième siège (Kweet) : Kevin Laird Nom de la Réalité : Kevin Laird Nom de la Vérité : Kriilf Dirtylairs Age : «65 ans » - ???? ans Affiliations : Crawlers : venomers Nationalité d’origine : américaine Ethnie réelle : Kweet Rang dans le syndicat : « Seigneur » Kevin laird est un sans-abri, il traine dans les égouts, les vieux métros et les quartiers abandonnés la nuit. Il a souvent de bonnes informations, mais il se fait payer en nourriture. Derrière son apparence repoussante de vieillard lubrique et sale, c’est en vérité un Venomer particulièrement sournois et manipulateur. Il connait très bien los Demonos mais sait qu’il y a une grande partie inaccessible, son rêve étant d’y pénétrer. Il a beau être sale, puant et sournois, c’est un seigneur du syndicat de Jade et un membre du conseil permanent de ce dernier même. Bien que les kweet ne vivent pas vieux, celui-ci a plus d’un millénaire, la raison étant qu’il protégea une enfant quand il était tout jeune, une humaine et il s’avéra que c’était l’Ancienne, mère des babayaga, laquelle lui vola sa mortalité en remerciement. Krrilf est un des rares exilé à bien connaitre les kochtchei et les babayaga, mais il le cache bien, comme sa maitresse il peut prendre l’apparence d’un enfant pour tromper ses ennemis en plus de son apparence de vieillard, sa projection humaine dans l’hologramme."},"sections":[{"id":"grands-exiles-informations-realite","title":"Informations · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Kevin Laird"],["Âge apparent","65 ans"],["Nationalité déclarée","américaine"]]}]},{"id":"grands-exiles-informations-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Troisième siège (Kweet) : Kevin Laird"],["Nom de la Réalité","Kevin Laird"],["Nom de la Vérité","Kriilf Dirtylairs"],["Âge source","«65 ans » - ???? ans"],["Affiliations","Crawlers : venomers"],["Nationalité d’origine","américaine"],["Nature réelle","Kweet"],["Rang dans le Syndicat","« Seigneur »"]]},{"type":"p","style":"lore","text":"Kevin laird est un sans-abri, il traine dans les égouts, les vieux métros et les quartiers abandonnés la nuit. Il a souvent de bonnes informations, mais il se fait payer en nourriture. Derrière son apparence repoussante de vieillard lubrique et sale, c’est en vérité un Venomer particulièrement sournois et manipulateur. Il connait très bien los Demonos mais sait qu’il y a une grande partie inaccessible, son rêve étant d’y pénétrer. Il a beau être sale, puant et sournois, c’est un seigneur du syndicat de Jade et un membre du conseil permanent de ce dernier même. Bien que les kweet ne vivent pas vieux, celui-ci a plus d’un millénaire, la raison étant qu’il protégea une enfant quand il était tout jeune, une humaine et il s’avéra que c’était l’Ancienne, mère des babayaga, laquelle lui vola sa mortalité en remerciement. Krrilf est un des rares exilé à bien connaitre les kochtchei et les babayaga, mais il le cache bien, comme sa maitresse il peut prendre l’apparence d’un enfant pour tromper ses ennemis en plus de son apparence de vieillard, sa projection humaine dans l’hologramme."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
